describe("Color.convert", () => {
  let colorInstance;

  beforeEach(() => {
    colorInstance = new Color();
  });

  it("should return black color if the color space is invalid", () => {
    jest.spyOn(Color, "_isValidSpace").mockReturnValue(false);
    const result = colorInstance.convert(["RGB", 1, 0, 0], "INVALID");
    expect(result).toEqual(colorInstance.black);
  });

  it("should return transparent color if the color space is 'T'", () => {
    jest.spyOn(Color, "_isValidSpace").mockReturnValue(true);
    const result = colorInstance.convert(["RGB", 1, 0, 0], "T");
    expect(result).toEqual(["T"]);
  });

  it("should return the same color array if the color space matches the input color space", () => {
    jest.spyOn(Color, "_isValidSpace").mockReturnValue(true);
    jest.spyOn(Color, "_getCorrectColor").mockImplementation((colorArray) => colorArray);
    const result = colorInstance.convert(["RGB", 1, 0, 0], "RGB");
    expect(result).toEqual(["RGB", 1, 0, 0]);
  });

  it("should convert transparent color to black and then to the target color space", () => {
    jest.spyOn(Color, "_isValidSpace").mockReturnValue(true);
    jest.spyOn(Color, "_getCorrectColor").mockImplementation((colorArray) => colorArray);
    const mockConverter = jest.spyOn(ColorConverters, "G_RGB").mockReturnValue(["RGB", 0, 0, 0]);
    const result = colorInstance.convert(["T"], "RGB");
    expect(mockConverter).toHaveBeenCalledWith([0]);
    expect(result).toEqual(["RGB", 0, 0, 0]);
  });

  it("should convert color using the appropriate converter function", () => {
    jest.spyOn(Color, "_isValidSpace").mockReturnValue(true);
    jest.spyOn(Color, "_getCorrectColor").mockImplementation((colorArray) => colorArray);
    const mockConverter = jest.spyOn(ColorConverters, "RGB_CMYK").mockReturnValue(["CMYK", 0, 1, 0, 0]);
    const result = colorInstance.convert(["RGB", 1, 0, 0], "CMYK");
    expect(mockConverter).toHaveBeenCalledWith([1, 0, 0]);
    expect(result).toEqual(["CMYK", 0, 1, 0, 0]);
  });
});

