    delete global.chrome;
  });

  it('should return early if mimeType is not application/pdf', () => {
    mockElem.type = 'application/json';
    contentscript.watchObjectOrEmbed(mockElem);
    expect(mockElem.__I_saw_this_element).toBeUndefined();
  });

  it('should return early if src/data attribute does not contain a PDF file', () => {
    mockElem.src = 'test.txt';
    contentscript.watchObjectOrEmbed(mockElem);
    expect(mockElem.__I_saw_this_element).toBeUndefined();
  });

  it('should return early for Chrome default page embedding a PDF file', () => {
    mockElem.name = 'plugin';
    mockElem.parentNode = document.body;
    document.body.appendChild(mockElem);
    mockElem.src = location.href;
    contentscript.watchObjectOrEmbed(mockElem);
    expect(mockElem.__I_saw_this_element).toBeUndefined();
  });

  it('should return early for internal embeds with "about:blank" src', () => {
    mockElem.src = 'about:blank';
    contentscript.watchObjectOrEmbed(mockElem);
    expect(mockElem.__I_saw_this_element).toBeUndefined();
  });

  it('should return early if element is already processed', () => {
    mockElem.__I_saw_this_element = true;
    contentscript.watchObjectOrEmbed(mockElem);
    expect(mockUpdateEmbedElement).not.toHaveBeenCalled();
    expect(mockUpdateObjectElement).not.toHaveBeenCalled();
  });

  it('should call updateEmbedElement for EMBED tag', () => {
    contentscript.watchObjectOrEmbed(mockElem);
    expect(mockElem.__I_saw_this_element).toBe(true);
    expect(mockUpdateEmbedElement).toHaveBeenCalledWith(mockElem);
  });

  it('should call updateObjectElement for OBJECT tag', () => {
    mockElem = document.createElement('object');
    mockElem.type = 'application/pdf';
    mockElem.data = 'test.pdf';
    contentscript.watchObjectOrEmbed(mockElem);
    expect(mockElem.__I_saw_this_element).toBe(true);
    expect(mockUpdateObjectElement).toHaveBeenCalledWith(mockElem);
  });

  it('should observe changes to src/data attribute and update viewer frame', () => {
    contentscript.watchObjectOrEmbed(mockElem);
    expect(mockElem.__I_saw_this_element).toBe(true);
    expect(mockUpdateEmbedElement).toHaveBeenCalledWith(mockElem);

    mockElem.src = 'new_test.pdf';
    const mutationEvent = new MutationEvent('attributes', { attributeName: 'src' });
    mockElem.dispatchEvent(mutationEvent);

    expect(mockUpdateEmbedElement).toHaveBeenCalledTimes(2);
    expect(mockUpdateEmbedElement).toHaveBeenCalledWith(mockElem);
  });

  it('should not update viewer frame if src/data attribute does not change', () => {
    contentscript.watchObjectOrEmbed(mockElem);
    expect(mockElem.__I_saw_this_element).toBe(true);
    expect(mockUpdateEmbedElement).toHaveBeenCalledWith(mockElem);

    const mutationEvent = new MutationEvent('attributes', { attributeName: 'src' });
    mockElem.dispatchEvent(mutationEvent);

    expect(mockUpdateEmbedElement).toHaveBeenCalledTimes(1);
  });
});

