const { validateResponseStatus } = require('../../../src/display/network_utils');

describe('validateResponseStatus', () => {
  test('should return true for status 200', () => {
    expect(validateResponseStatus(200)).toBe(true);
  });

  test('should return true for status 206', () => {
    expect(validateResponseStatus(206)).toBe(true);
  });

  test('should return false for status 404', () => {
    expect(validateResponseStatus(404)).toBe(false);
  });

  test('should return false for status 500', () => {
    expect(validateResponseStatus(500)).toBe(false);
  });

  test('should return false for status 0', () => {
    expect(validateResponseStatus(0)).toBe(false);
  });

  test('should return false for undefined status', () => {
    expect(validateResponseStatus(undefined)).toBe(false);
  });

  test('should return false for null status', () => {
    expect(validateResponseStatus(null)).toBe(false);
  });

  test('should return false for non-numeric status', () => {
    expect(validateResponseStatus('200')).toBe(false);
    expect(validateResponseStatus('206')).toBe(false);
    expect(validateResponseStatus('error')).toBe(false);
  });
});

