const { InfoProxyHandler } = require('../../../src/scripting_api/doc');

describe('InfoProxyHandler.get', () => {
  test('should return the value of the property in lowercase', () => {
    const obj = { name: 'John', age: 30 };
    const result = InfoProxyHandler.prototype.get(obj, 'NAME');
    expect(result).toBe('John');
  });

  test('should return undefined for a non-existent property', () => {
    const obj = { name: 'John', age: 30 };
    const result = InfoProxyHandler.prototype.get(obj, 'nonExistentProp');
    expect(result).toBeUndefined();
  });

  test('should handle numeric property names correctly', () => {
    const obj = { '123': 'value123' };
    const result = InfoProxyHandler.prototype.get(obj, '123');
    expect(result).toBe('value123');
  });

  test('should handle mixed-case property names correctly', () => {
    const obj = { mixedCase: 'value' };
    const result = InfoProxyHandler.prototype.get(obj, 'MIXEDCASE');
    expect(result).toBe('value');
  });

  test('should handle empty string property names correctly', () => {
    const obj = { '': 'emptyValue' };
    const result = InfoProxyHandler.prototype.get(obj, '');
    expect(result).toBe('emptyValue');
  });

  test('should handle properties with special characters', () => {
    const obj = { 'prop-with-dash': 'value' };
    const result = InfoProxyHandler.prototype.get(obj, 'PROP-WITH-DASH');
    expect(result).toBe('value');
  });

  test('should handle properties with spaces', () => {
    const obj = { 'property with space': 'value' };
    const result = InfoProxyHandler.prototype.get(obj, 'PROPERTY WITH SPACE');
    expect(result).toBe('value');
  });

  test('should handle properties with symbols', () => {
    const obj = { '@symbolProp': 'value' };
    const result = InfoProxyHandler.prototype.get(obj, '@SYMBOLPROP');
    expect(result).toBe('value');
  });
});

