    const instance1 = new MurmurHash3_64(0xabcdef01);
    const instance2 = new MurmurHash3_64(0x12345678);

    const result1 = instance1.hexdigest();
    const result2 = instance2.hexdigest();

    expect(result1).not.toBe(result2);
  });

  test("should handle edge case with seed 0", () => {
    const instanceZeroSeed = new MurmurHash3_64(0);
    const result = instanceZeroSeed.hexdigest();
    expect(result).toMatch(/^[0-9a-f]{16}$/);
  });

  test("should handle edge case with maximum seed value", () => {
    const maxSeed = 0xffffffff;
    const instanceMaxSeed = new MurmurHash3_64(maxSeed);
    const result = instanceMaxSeed.hexdigest();
    expect(result).toMatch(/^[0-9a-f]{16}$/);
  });
});

