describe("PDFPageView.cancelRendering", () => {
  let pdfPageView;
  let mockTextLayer, mockAnnotationLayer, mockAnnotationEditorLayer, mockXfaLayer, mockDrawLayer;

  beforeEach(() => {
    mockTextLayer = {
      cancel: jest.fn(),
      div: true,
    };
    mockAnnotationLayer = {
      cancel: jest.fn(),
      div: true,
    };
    mockAnnotationEditorLayer = {
      cancel: jest.fn(),
      div: true,
    };
    mockXfaLayer = {
      cancel: jest.fn(),
      div: true,
    };
    mockDrawLayer = {
      cancel: jest.fn(),
    };

    pdfPageView = new PDFPageView({
      container: document.createElement("div"),
      defaultViewport: { rotation: 0 },
    });

    pdfPageView.textLayer = mockTextLayer;
    pdfPageView.annotationLayer = mockAnnotationLayer;
    pdfPageView.annotationEditorLayer = mockAnnotationEditorLayer;
    pdfPageView.xfaLayer = mockXfaLayer;
    pdfPageView.drawLayer = mockDrawLayer;
    pdfPageView._annotationCanvasMap = {};
    pdfPageView.structTreeLayer = {};
  });

  it("should cancel all layers and reset properties when no options are provided", () => {
    pdfPageView.cancelRendering();

    expect(mockTextLayer.cancel).toHaveBeenCalled();
    expect(pdfPageView.textLayer).toBeNull();

    expect(mockAnnotationLayer.cancel).toHaveBeenCalled();
    expect(pdfPageView.annotationLayer).toBeNull();
    expect(pdfPageView._annotationCanvasMap).toBeNull();

    expect(mockAnnotationEditorLayer.cancel).toHaveBeenCalled();
    expect(mockDrawLayer.cancel).toHaveBeenCalled();
    expect(pdfPageView.annotationEditorLayer).toBeNull();
    expect(pdfPageView.drawLayer).toBeNull();

    expect(mockXfaLayer.cancel).toHaveBeenCalled();
    expect(pdfPageView.xfaLayer).toBeNull();

    expect(pdfPageView.structTreeLayer).toBeNull();
  });

  it("should keep the text layer when keepTextLayer is true", () => {
    pdfPageView.cancelRendering({ keepTextLayer: true });

    expect(mockTextLayer.cancel).not.toHaveBeenCalled();
    expect(pdfPageView.textLayer).toBe(mockTextLayer);
  });

  it("should keep the annotation layer when keepAnnotationLayer is true", () => {
    pdfPageView.cancelRendering({ keepAnnotationLayer: true });

    expect(mockAnnotationLayer.cancel).not.toHaveBeenCalled();
    expect(pdfPageView.annotationLayer).toBe(mockAnnotationLayer);
    expect(pdfPageView._annotationCanvasMap).not.toBeNull();
  });

  it("should keep the annotation editor layer when keepAnnotationEditorLayer is true", () => {
    pdfPageView.cancelRendering({ keepAnnotationEditorLayer: true });

    expect(mockAnnotationEditorLayer.cancel).not.toHaveBeenCalled();
    expect(mockDrawLayer.cancel).not.toHaveBeenCalled();
    expect(pdfPageView.annotationEditorLayer).toBe(mockAnnotationEditorLayer);
    expect(pdfPageView.drawLayer).toBe(mockDrawLayer);
  });

  it("should keep the XFA layer when keepXfaLayer is true", () => {
    pdfPageView.cancelRendering({ keepXfaLayer: true });

    expect(mockXfaLayer.cancel).not.toHaveBeenCalled();
    expect(pdfPageView.xfaLayer).toBe(mockXfaLayer);
  });

  it("should reset structTreeLayer only when textLayer is null", () => {
    pdfPageView.textLayer = null;

    pdfPageView.cancelRendering();

    expect(pdfPageView.structTreeLayer).toBeNull();
  });

  it("should not reset structTreeLayer when textLayer is not null", () => {
    pdfPageView.cancelRendering();

    expect(pdfPageView.structTreeLayer).not.toBeNull();
  });
});

