  });

  it("should handle cloning when the dictionary is empty", () => {
    const emptyDict = new Dict();
    const clonedDict = new Dict();
    jest.spyOn(emptyDict, "clone").mockReturnValue(clonedDict);

    const result = pdfEditor.cloneDict(emptyDict);

    expect(emptyDict.clone).toHaveBeenCalled();
    expect(result).toBe(clonedDict);
    expect(result.xref).toBe(pdfEditor.xrefWrapper);
  });

  it("should throw an error if the input is not a dictionary", () => {
    const invalidInput = null;

    expect(() => pdfEditor.cloneDict(invalidInput)).toThrow();
  });
});

