  test('should convert CMYK values to RGB correctly', () => {
    const input = [0.2, 0.3, 0.4, 0.1];
    const expectedOutput = [
      Math.round((1 - Math.min(1, input[0] + input[3])) * 255),
      Math.round((1 - Math.min(1, input[1] + input[3])) * 255),
      Math.round((1 - Math.min(1, input[2] + input[3])) * 255),
