  let mockStorageAreaSet;
  let mockImportTemplate;
  let originalDocument;

  beforeEach(() => {
    // Mock storageArea.set
    mockStorageAreaSet = jest.fn();
    global.storageArea = { set: mockStorageAreaSet };

    // Mock importTemplate
    mockImportTemplate = jest.fn(() => {
      const wrapper = document.createElement('div');
      wrapper.title = '';
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      wrapper.appendChild(checkbox);
      const span = document.createElement('span');
      wrapper.appendChild(span);
      return wrapper;
    });
    global.importTemplate = mockImportTemplate;

    // Mock document
    originalDocument = global.document;
    const mockDocument = {
      getElementById: jest.fn(() => {
        const settingsBox = document.createElement('div');
        settingsBox.id = 'settings-boxes';
        return settingsBox;
      }),
    };
    global.document = mockDocument;
  });

  afterEach(() => {
    jest.clearAllMocks();
    global.document = originalDocument;
  });

  it('should render the checkbox with the correct title and short description', () => {
    const shortDescription = 'Enable feature';
    const description = 'Enable or disable the feature';
    const prefName = 'featureEnabled';

    renderBooleanPref(shortDescription, description, prefName);

    expect(mockImportTemplate).toHaveBeenCalledWith('checkbox-template');
    const wrapper = mockImportTemplate.mock.results[0].value;
    expect(wrapper.title).toBe(description);
    expect(wrapper.querySelector('span').textContent).toBe(shortDescription);
    expect(global.document.getElementById).toHaveBeenCalledWith('settings-boxes');
    expect(global.document.getElementById('settings-boxes').append).toHaveBeenCalledWith(wrapper);
  });

  it('should update the preference in storageArea when the checkbox is toggled', () => {
    const shortDescription = 'Enable feature';
    const description = 'Enable or disable the feature';
    const prefName = 'featureEnabled';

    renderBooleanPref(shortDescription, description, prefName);

    const wrapper = mockImportTemplate.mock.results[0].value;
    const checkbox = wrapper.querySelector('input[type="checkbox"]');

    checkbox.checked = true;
    checkbox.onchange();

    expect(mockStorageAreaSet).toHaveBeenCalledWith({ [prefName]: true });

    checkbox.checked = false;
    checkbox.onchange();

    expect(mockStorageAreaSet).toHaveBeenCalledWith({ [prefName]: false });
  });

  it('should return a renderPreference function that updates the checkbox state', () => {
    const shortDescription = 'Enable feature';
    const description = 'Enable or disable the feature';
    const prefName = 'featureEnabled';

    const renderPreference = renderBooleanPref(shortDescription, description, prefName);

    const wrapper = mockImportTemplate.mock.results[0].value;
    const checkbox = wrapper.querySelector('input[type="checkbox"]');

    renderPreference(true);
    expect(checkbox.checked).toBe(true);

    renderPreference(false);
    expect(checkbox.checked).toBe(false);
  });
});

